// The guest's email and the hotel's notice, built from the database row — exact dates, room and ticket,
// in the guest's language. Kind: confirmed.
const r = $('Confirm').first().json.r || {};
const kind = 'confirmed';
const L = ['sq', 'sr', 'en'].includes(r.language) ? r.language : 'en';
const locale = { sq: 'sq-AL', sr: 'sr-Latn-ME', en: 'en-GB' }[L];
const day = (d) => { try { return new Intl.DateTimeFormat(locale, { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' }).format(new Date(String(d) + 'T00:00:00Z')); } catch (e) { return String(d); } };
const first = String(r.first_name || '').trim() || String(r.guest || '').split(' ')[0] || '';
const hotel = String(r.hotel || '').trim();
const type = r.room_type ? ' (' + r.room_type + ')' : '';
const stay = r.room + ', ' + day(r.check_in) + ' - ' + day(r.check_out);
const T = {
  en: { hi: 'Dear ' + first + ',', team: 'The reception team',
        cSubj: 'Booking confirmed - ' + r.ticket, cHead: hotel ? 'Your booking at ' + hotel + ' is confirmed.' : 'Your booking is confirmed.',
        ref: 'Booking reference', room: 'Room', guests: 'Guests', cin: 'Check-in', cout: 'Check-out', from: 'from', by: 'by', nights: 'Nights',
        change: 'To change or cancel your booking, write to us in the chat and mention your booking reference.', bye: 'We look forward to welcoming you!',
        xSubj: 'Booking cancelled - ' + r.ticket, xHead: 'Your booking ' + r.ticket + ' (room ' + stay + ') has been cancelled.',
        xHelp: 'If this was a mistake, write to us in the chat and we will gladly help.' },
  sq: { hi: 'Përshëndetje ' + first + ',', team: 'Ekipi i recepsionit',
        cSubj: 'Rezervimi u konfirmua - ' + r.ticket, cHead: hotel ? 'Rezervimi juaj në ' + hotel + ' është konfirmuar.' : 'Rezervimi juaj është konfirmuar.',
        ref: 'Numri i rezervimit', room: 'Dhoma', guests: 'Numri i mysafirëve', cin: 'Hyrja', cout: 'Dalja', from: 'nga ora', by: 'deri në orën', nights: 'Netë',
        change: 'Për të ndryshuar ose anuluar rezervimin, na shkruani në bisedë dhe përmendni numrin e rezervimit.', bye: 'Ju mirëpresim!',
        xSubj: 'Rezervimi u anulua - ' + r.ticket, xHead: 'Rezervimi juaj ' + r.ticket + ' (dhoma ' + stay + ') është anuluar.',
        xHelp: 'Nëse kjo është gabim, na shkruani në bisedë dhe ju ndihmojmë me kënaqësi.' },
  sr: { hi: 'Dobar dan, ' + first + ',', team: 'Recepcija',
        cSubj: 'Rezervacija potvrđena - ' + r.ticket, cHead: 'Vaša rezervacija je potvrđena' + (hotel ? ' - ' + hotel : '') + '.',
        ref: 'Broj rezervacije', room: 'Soba', guests: 'Broj gostiju', cin: 'Prijava', cout: 'Odjava', from: 'od', by: 'do', nights: 'Broj noćenja',
        change: 'Za izmjenu ili otkazivanje rezervacije pišite nam u razgovoru i navedite broj rezervacije.', bye: 'Radujemo se Vašem dolasku!',
        xSubj: 'Rezervacija otkazana - ' + r.ticket, xHead: 'Vaša rezervacija ' + r.ticket + ' (soba ' + stay + ') je otkazana.',
        xHelp: 'Ako je u pitanju greška, pišite nam u razgovoru i rado ćemo Vam pomoći.' },
}[L];
const sign = hotel || T.team;
const subject = kind === 'confirmed' ? T.cSubj : T.xSubj;
const message = kind === 'confirmed'
  ? [T.hi, '', T.cHead, '', T.ref + ': ' + r.ticket, T.room + ': ' + r.room + type, T.guests + ': ' + r.guests,
     T.cin + ': ' + day(r.check_in) + ', ' + T.from + ' ' + r.check_in_time, T.cout + ': ' + day(r.check_out) + ', ' + T.by + ' ' + r.check_out_time,
     T.nights + ': ' + r.nights, '', T.change, '', T.bye, sign].join('\n')
  : [T.hi, '', T.xHead, '', T.xHelp, '', sign].join('\n');
const who = String(r.guest || '').trim() || (String(r.first_name || '') + ' ' + String(r.last_name || '')).trim();
const conv = r.conversation_id ? 'http://localhost:3000/app/accounts/' + r.account_id + '/conversations/' + r.conversation_id : 'http://localhost:3000';
const hotelSubject = (kind === 'confirmed' ? 'New booking: ' : 'Booking cancelled: ') + 'room ' + r.room + ', ' + r.check_in + ' -> ' + r.check_out + ' (' + r.ticket + ')';
const hotelText = [kind === 'confirmed' ? 'A guest booked through Receply.' : 'A guest cancelled through Receply.', '',
  'Ticket: ' + r.ticket + (r.booking_no ? ' (booking no. ' + r.booking_no + ')' : ''), 'Guest: ' + who,
  r.phone ? 'Phone: ' + r.phone : null, r.email ? 'Email: ' + r.email : null, 'Room: ' + r.room + type,
  r.guests ? 'Guests: ' + r.guests : null, 'Check-in: ' + r.check_in + (r.check_in_time ? ' ' + r.check_in_time : ''),
  'Check-out: ' + r.check_out + (r.check_out_time ? ' ' + r.check_out_time : ''), 'Channel: ' + (r.channel || 'chat'), 'Conversation: ' + conv, '',
  'All reservations: the "Reservations (Receply)" tab of your Google Sheet.'].filter((x) => x !== null).join('\n');
return [{ json: { to: String(r.email || '').trim(), subject, message, hotelTo: r.owner_email || 'oltshala@gmail.com', hotelSubject, hotelText,
  topic: r.alert_topic || '__RL_TOPIC__', click: conv,
  pushTitle: kind === 'confirmed' ? 'Receply - new booking' : 'Receply - booking cancelled',
  pushText: (kind === 'confirmed' ? '📅 ' : '❌ ') + who + ': room ' + r.room + ', ' + r.check_in + ' -> ' + r.check_out + (r.guests ? ', ' + r.guests + ' guest(s)' : '') + ' (' + r.ticket + ')' } }];
